/*
 * A070909  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 28" and by "Rule 156".
 * https://oeis.org/A070909
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl
 * Formula:   not stated
 * Range:     u8 n <= 98, u16 n <= 98, u32 n <= 98, u64 n <= 98, u128 n <= 98,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A070909:  a(n) is the nth element of the triangle obtained by successive
   states of elementary cellular automaton Rule 28, starting from a single cell 1
   and reading rows left‑to‑right.  a(0)=1, a(1)=1, a(2)=1, a(3)=1, a(4)=0, a(5)=1, … */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* ---------------------------------------------
       static cache for already computed values
       --------------------------------------------- */
    static seq_t *cache = NULL;          /* flattened sequence          */
    static size_t cache_cap = 0;         /* allocated capacity          */
    static size_t cache_len = 0;         /* number of elements cached   */

    /* ---------------------------------------------
       static buffers for the last two rows of the CA
       --------------------------------------------- */
    static seq_t *row_cur  = NULL;       /* current row (length cur_len)*/
    static size_t cur_len = 0;           /* length of current row       */
    static seq_t *row_next = NULL;       /* buffer for next row         */

    /* initialization on first call */
    if (cache == NULL) {
        /* reserve a small initial capacity */
        cache_cap = 32;
        cache = (seq_t *)malloc(sizeof(seq_t) * cache_cap);
        /* first row: a single 1 */
        cache[0] = (seq_t)1;
        cache_len = 1;

        /* initialise CA rows */
        cur_len  = 1;
        row_cur  = (seq_t *)malloc(sizeof(seq_t) * cur_len);
        row_cur[0] = (seq_t)1;
        row_next = (seq_t *)malloc(sizeof(seq_t) * (cur_len + 1));
    }

    /* enlarge cache if necessary */
    if ((idx_t)(n + 1) > (idx_t)cache_cap) {
        size_t new_cap = cache_cap * 2;
        if (new_cap < (size_t)(n + 1))
            new_cap = n + 1;
        cache = (seq_t *)realloc(cache, sizeof(seq_t) * new_cap);
        cache_cap = new_cap;
    }

    /* ------------------------------------------------------------------
       generate new rows of the CA until cache contains at least n+1 terms
       ------------------------------------------------------------------ */
    while (cache_len <= n) {
        /* next row has length cur_len + 1 */
        size_t next_len = cur_len + 1;
        row_next = (seq_t *)realloc(row_next, sizeof(seq_t) * next_len);

        /* compute the next row according to Rule 28:
           output = 1 when pattern is 100, 011 or 010 */
        for (idx_t j = 0; j < (idx_t)next_len; ++j) {
            int left   = (j > 0   && (size_t)(j - 1) < cur_len) ? (int)row_cur[j - 1] : 0;
            int center = (j < (idx_t)cur_len)                    ? (int)row_cur[j]     : 0;
            int right  = (j + 1 < (idx_t)cur_len)                ? (int)row_cur[j + 1] : 0;
            int pat = (left << 2) | (center << 1) | right;
            seq_t out = (pat == 4 || pat == 3 || pat == 2) ? (seq_t)1 : (seq_t)0;
            row_next[j] = out;
        }

        /* append the new row to the flat cache */
        for (idx_t j = 0; j < (idx_t)next_len; ++j) {
            if (cache_len == cache_cap) {
                cache_cap *= 2;
                cache = (seq_t *)realloc(cache, sizeof(seq_t) * cache_cap);
            }
            cache[cache_len++] = row_next[j];
        }

        /* prepare for next iteration: the new row becomes current */
        seq_t *tmp = row_cur;
        row_cur = row_next;
        row_next = tmp;
        cur_len = next_len;
    }

    return cache[n];
}
